import { ChevronRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';

import { Constellation } from './constellation';
import { AREAS, SECTION } from './data';

const CARD_SURFACE =
  'bg-card hairline-ring ring-border rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)] dark:bg-foreground/[0.03]';

const ALL_BRANDS = AREAS.flatMap((area) => area.brands);

function toolCountOf(count: number) {
  if (count === 1) {
    return '1 tool';
  }
  return `${count} tools`;
}

function areaCountOf(count: number) {
  if (count === 1) {
    return '1 area';
  }
  return `${count} areas`;
}

const LEAD = `${toolCountOf(ALL_BRANDS.length)} in ${areaCountOf(AREAS.length)}. ${SECTION.description}`;

export default function Integrations03() {
  return (
    <section className='px-4 py-16 sm:px-6 sm:py-24 lg:px-8'>
      <div className='mx-auto flex max-w-6xl flex-col gap-10'>
        <div className='flex max-w-2xl flex-col gap-3'>
          <h2 className='text-2xl font-semibold text-balance sm:text-3xl'>
            {SECTION.title}
          </h2>
          <p className='text-muted-foreground text-base text-pretty'>{LEAD}</p>
        </div>
        <ul className='grid gap-4 lg:grid-cols-2'>
          {AREAS.map((area) => (
            <li
              key={area.id}
              className={cn(
                CARD_SURFACE,
                'flex flex-col gap-1.5 p-1.5 sm:flex-row'
              )}
            >
              <div className='flex flex-1 flex-col items-start p-3.5 sm:p-4'>
                <div className='flex w-full items-baseline justify-between gap-3'>
                  <h3 className='text-base font-semibold text-balance'>
                    {area.title}
                  </h3>
                  <span className='text-muted-foreground shrink-0 text-xs tabular-nums'>
                    {toolCountOf(area.brands.length)}
                  </span>
                </div>
                <p className='text-muted-foreground mt-2 text-sm leading-relaxed text-pretty'>
                  {area.description}
                </p>
                <div className='mt-auto pt-4'>
                  <Button
                    variant='link'
                    className='h-auto px-0'
                    nativeButton={false}
                    render={<a href='#' />}
                  >
                    {area.linkLabel}
                    <ChevronRightIcon className='size-3.5' />
                  </Button>
                </div>
              </div>
              <div className='bg-foreground/[0.025] flex shrink-0 items-center justify-center rounded-[calc(var(--radius-xl)-0.375rem)] sm:w-60'>
                <Constellation
                  label={`${area.title} tools`}
                  brands={area.brands}
                />
              </div>
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}

import {
  BRANDS,
  BrandLogo,
  type BrandSlug,
} from '@/registry/ndeko/lib/brand-logos';

type Slot = {
  left: string;
  top: string;
};

/** Three staggered rows, two, three and two marks, like cells of a honeycomb. */
const SLOTS: Slot[] = [
  { left: '50%', top: '50%' },
  { left: '34%', top: '15%' },
  { left: '66%', top: '15%' },
  { left: '20%', top: '50%' },
  { left: '80%', top: '50%' },
  { left: '34%', top: '85%' },
  { left: '66%', top: '85%' },
];

const FLOAT_STEP_SECONDS = 0.85;

function floatStyleOf(index: number): React.CSSProperties {
  const seconds = index * FLOAT_STEP_SECONDS;
  return { animationDelay: `-${seconds}s` };
}

type ConstellationProps = {
  label: string;
  brands: BrandSlug[];
};

export function Constellation({ label, brands }: ConstellationProps) {
  const shown = brands.slice(0, SLOTS.length);

  return (
    <ul aria-label={label} className='relative h-40 w-52'>
      {shown.map((brand, index) => {
        const slot = SLOTS[index];
        const title = BRANDS[brand].title;

        return (
          <li
            key={brand}
            style={slot}
            className='absolute -translate-x-1/2 -translate-y-1/2'
          >
            <span
              style={floatStyleOf(index)}
              className='keycap-3d animate-float flex size-9 items-center justify-center rounded-full motion-reduce:animate-none'
            >
              <BrandLogo brand={brand} title={title} />
            </span>
          </li>
        );
      })}
    </ul>
  );
}

import type { BrandSlug } from '@/registry/ndeko/lib/brand-logos';

export type ToolArea = {
  id: string;
  title: string;
  description: string;
  linkLabel: string;
  brands: BrandSlug[];
};

export const SECTION = {
  title: 'Integrations by what they help with',
  description:
    'Each tool adds what it knows to the task it is about, and disconnects from the same page in Fernhollow.',
};

export const AREAS: ToolArea[] = [
  {
    id: 'communication',
    title: 'Communication',
    description:
      'Calls, chats and mail that point back to the task they are about.',
    linkLabel: 'See communication tools',
    brands: [
      'gmail',
      'element',
      'zoom',
      'googlemeet',
      'telegram',
      'loom',
      'mattermost',
    ],
  },
  {
    id: 'files',
    title: 'Files and docs',
    description:
      'Attach files and pages without copying them, and keep their titles current.',
    linkLabel: 'See file and doc tools',
    brands: [
      'notion',
      'googledrive',
      'dropbox',
      'figma',
      'googledocs',
      'confluence',
      'box',
    ],
  },
  {
    id: 'finance',
    title: 'Finance',
    description:
      'Approved hours and expenses go to invoices, payroll and your books.',
    linkLabel: 'See finance tools',
    brands: [
      'stripe',
      'quickbooks',
      'xero',
      'paypal',
      'gusto',
      'square',
      'revolut',
    ],
  },
  {
    id: 'developer',
    title: 'Developer',
    description:
      'Pull requests, issues, errors and deploys update the tasks they mention.',
    linkLabel: 'See developer tools',
    brands: [
      'github',
      'linear',
      'gitlab',
      'jira',
      'sentry',
      'bitbucket',
      'zapier',
    ],
  },
];
